$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ClosureResults";$name='m78-closure-moved-package'
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
if(Test-Path "$out\$name.json"){throw 'Preserve existing smoke receipt'};$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-closure-prior-moved-manifest.json").Content|ConvertFrom-Json;$runtime=(Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-runtime-build.json").Content|ConvertFrom-Json;$package="$root\M78ClosurePackage";$moved="$root\M78ClosureMovedPackage";if((Test-Path $package) -or (Test-Path $moved)){throw 'Preserve existing closure package'}
foreach($f in $m.packageFiles){$p=Join-Path $m.priorPackage $f.path;if((Get-Item $p).Length -ne $f.bytes -or (Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw 'Prior ordinary package bytes changed'}}
if((Get-PSDrive C).Free -lt ($runtime.executableBytes+4MB)){throw 'Insufficient bounded package runtime headroom'};New-Item -ItemType Directory $package|Out-Null
foreach($f in $m.packageFiles){$dest=Join-Path $package $f.path;New-Item -ItemType Directory ([IO.Path]::GetDirectoryName($dest)) -Force|Out-Null;if($f.path -ne 'judas.exe'){New-Item -ItemType HardLink -Path $dest -Target (Join-Path $m.priorPackage $f.path)|Out-Null}}
Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-runtime-m78-closure-runtime.exe.bin" -OutFile "$package\judas.exe";if((Get-Item "$package\judas.exe").Length -ne $runtime.executableBytes -or (Get-FileHash "$package\judas.exe").Hash.ToLower() -ne $runtime.executableSHA256){throw 'Final runtime identity mismatch'}
Move-Item $package $moved;$h="$out\moved-services.harness";Invoke-WebRequest -UseBasicParsing "$base/m78-continuation-moved-services.harness" -OutFile $h;if((Get-FileHash $h).Hash.ToLower() -ne '6f975418b9e6f0a2af2644c509bc98115be2407db0e8f0afae88d092e149ef1d'){throw 'Original services harness changed'}
$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_TEST_SCRIPT=$h;$env:JUDAS_ENGINE_ROOT='C:\JudasValidation\UnavailableEngineRoot';$env:TEMP="$out\package-temp";$env:TMP=$env:TEMP;$env:APPDATA="$out\package-userdata\Roaming";$env:LOCALAPPDATA="$out\package-userdata\Local";New-Item -ItemType Directory $env:TEMP,$env:APPDATA,$env:LOCALAPPDATA -Force|Out-Null;$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath "$moved\judas.exe" -WorkingDirectory 'C:\Windows\Temp' -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;throw 'Only owned package timeout'};$p.Refresh();$exit=$p.ExitCode;$p.Dispose();$watch.Stop();$files=@(Get-ChildItem $moved -Recurse -File|ForEach-Object {@{path=$_.FullName.Substring($moved.Length+1);bytes=$_.Length;sha256=(Get-FileHash $_.FullName).Hash.ToLower()}})
@{scope='Actual final closure runtime in byte-verified previously exported ordinary package content. NEW package tree moved and launched without arguments from unrelated cwd, unavailable engine root; original1720frame four-scene/save/load/pause/reload harness. This is final-runtime moved-package smoke, not a fresh export-generator invocation. Unchanged package files use NTFS hardlinks only to bound existing disk; original package untouched. VM softwareGL functional only.';exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;runtimeSHA256=$runtime.executableSHA256;archive=$runtime.archive;objects=$runtime.replacementObjects;priorPackageReceiptSHA256=$m.receiptSHA256;verifiedPriorFiles=$m.packageFiles.Count;packageFiles=$files;movedPath=$moved;cwd='C:\Windows\Temp';arguments=@();harnessSHA256=(Get-FileHash $h).Hash.ToLower();freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 7|Set-Content "$out\$name.json" -Encoding UTF8;Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload "$out\$name.json" "$name.json";if($exit -ne 0){throw 'Final package functional failure'}
}catch{$_|Out-String|Set-Content "$out\$name-error.txt";Upload "$out\$name-error.txt" "$name-error.txt";exit 1}
